// Author: MiYu. Classic scalar and sparse array storage retains values across callback invocations.
#include "jass_binary_storage.h"
#include "snapshot_codec.h"
#include <stdexcept>

namespace war3 {
namespace {
JassBinaryNativeValue coerce(JassBinaryNativeValue value,std::uint8_t type){if(value.type==2 && !value.bits && !value.text && (type==3 || type==6 || type==7))value.type=type;if(value.type!=type || (type==8 && value.bits>1) || (type!=6 && value.text) || (type==6 && value.bits && value.text) || (type==3 && value.bits && (value.code.bits!=value.bits || !value.code.codeOwner)))throw std::runtime_error("Invalid 2SAJ stored value");return value;}
}
JassBinaryStorage::JassBinaryStorage(const std::map<std::string,JassBinaryGlobal>& globals){if(globals.size()>65536)throw std::runtime_error("2SAJ global storage budget exceeded");for(auto& [name,global]:globals){auto type=global.value.type;if(name.empty() || type<3 || type>13 || (type>=9 && global.value.bits) || (type==3 && global.value.bits) || (type==8 && global.value.bits>1))throw std::runtime_error("Invalid 2SAJ global storage");entries_.emplace(name,Entry{{type,global.value.bits,{}},global.constant,{}});}}
bool JassBinaryStorage::contains(const std::string& name) const{return entries_.contains(name);}
std::uint8_t JassBinaryStorage::type(const std::string& name) const{auto it=entries_.find(name);if(it==entries_.end())throw std::runtime_error("Unknown 2SAJ global: "+name);return it->second.value.type;}
JassBinaryNativeValue JassBinaryStorage::read(const std::string& name) const{auto it=entries_.find(name);if(it==entries_.end() || it->second.value.type>=9)throw std::runtime_error("Unknown or array 2SAJ global: "+name);return it->second.value;}
void JassBinaryStorage::write(const std::string& name,JassBinaryNativeValue value){auto it=entries_.find(name);if(it==entries_.end() || it->second.constant || it->second.value.type>=9)throw std::runtime_error("Invalid 2SAJ global write: "+name);it->second.value=coerce(std::move(value),it->second.value.type);}
JassBinaryNativeValue JassBinaryStorage::readArray(const std::string& name,std::uint32_t index,std::uint8_t type) const{auto it=entries_.find(name);if(it==entries_.end() || type<4 || type>8 || it->second.value.type!=type+5)throw std::runtime_error("Invalid 2SAJ global array read: "+name);if(index<8192)if(auto found=it->second.elements.find(index);found!=it->second.elements.end())return found->second;return {type,0,{}};}
void JassBinaryStorage::writeArray(const std::string& name,std::uint32_t index,JassBinaryNativeValue value){auto it=entries_.find(name);if(it==entries_.end() || it->second.constant || it->second.value.type<9 || it->second.value.type>13)throw std::runtime_error("Invalid 2SAJ global array write: "+name);value=coerce(std::move(value),std::uint8_t(it->second.value.type-5));if(index>=8192)return;auto& array=it->second.elements;auto found=array.find(index);if(found==array.end()){if(elementCount_>=262144)throw std::runtime_error("2SAJ array storage budget exceeded");array.emplace(index,std::move(value));++elementCount_;}else found->second=std::move(value);}

Bytes JassBinaryStorage::encodeGlobals(const JassBinarySnapshotRefs& refs) const{
    constexpr size_t budget=32u*1024u*1024u,nameBudget=65536,stringBudget=16u*1024u*1024u;SnapshotWriter out(budget-64);out.u32(tag("BGLB"));out.u32(1);out.size(entries_.size());
    auto value=[&](const JassBinaryNativeValue& item,std::uint8_t type){auto v=coerce(item,type);if(type==6 && v.bits && refs.symbolCount && v.bits>*refs.symbolCount)throw std::runtime_error("Invalid 2SAJ snapshot string symbol");out.u32(v.type);if(type==3){if(v.bits){if(!refs.encodeCode)throw std::runtime_error("2SAJ snapshot code mapper unavailable");auto name=refs.encodeCode(v.code);if(name.empty() || name.find('\0')!=name.npos)throw std::runtime_error("Invalid 2SAJ snapshot code");out.u32(1);out.text(name,nameBudget);}else out.u32(0);}else{auto bits=v.bits;if(type==7 && bits){if(!refs.handle || !(bits=refs.handle(bits)))throw std::runtime_error("2SAJ snapshot handle mapper unavailable or invalid");}out.u32(bits);if(type==6){out.u32(v.text?1:0);if(v.text)out.text(*v.text,stringBudget);}}};
    size_t elements=0;for(auto& [name,entry]:entries_){out.text(name,nameBudget);out.u32(entry.value.type);out.u32(entry.constant?1:0);if(entry.value.type>=9){if(entry.elements.size()>8192 || entry.elements.size()>262144-elements)throw std::runtime_error("2SAJ snapshot array budget exceeded");elements+=entry.elements.size();out.size(entry.elements.size());for(auto& [index,item]:entry.elements){if(index>=8192)throw std::runtime_error("Invalid 2SAJ snapshot array index");out.u32(index);value(item,std::uint8_t(entry.value.type-5));}}else value(entry.value,entry.value.type);}if(elements!=elementCount_)throw std::runtime_error("Invalid 2SAJ snapshot array count");return sealSnapshot(out.finish(),budget);
}
void JassBinaryStorage::restoreGlobals(std::span<const std::uint8_t> bytes,const JassBinarySnapshotRefs& refs){
    constexpr size_t budget=32u*1024u*1024u,nameBudget=65536,stringBudget=16u*1024u*1024u;Binary in(openSnapshot(bytes,budget));in.expect(tag("BGLB"));if(in.u32()!=1 || in.u32()!=entries_.size())throw std::runtime_error("2SAJ snapshot schema differs");auto pending=entries_;size_t elements=0;
    auto value=[&](std::uint8_t type){if(in.u32()!=type)throw std::runtime_error("2SAJ snapshot value type differs");JassBinaryNativeValue v{type,0,{}};if(type==3){auto present=in.u32();if(present>1)throw std::runtime_error("Invalid 2SAJ snapshot code marker");if(present){auto name=snapshotText(in,nameBudget);if(name.empty() || name.find('\0')!=name.npos || !refs.decodeCode)throw std::runtime_error("2SAJ snapshot code mapper unavailable or invalid");v.code=refs.decodeCode(name);v.bits=v.code.bits;if(!v.bits || !v.code.codeOwner)throw std::runtime_error("Invalid 2SAJ restored code reference");}}else{v.bits=in.u32();if(type==7 && v.bits){if(!refs.handle || !(v.bits=refs.handle(v.bits)))throw std::runtime_error("2SAJ snapshot handle mapper unavailable or invalid");}if(type==6){auto present=in.u32();if(present>1 || (present && v.bits))throw std::runtime_error("Invalid 2SAJ snapshot string marker");if(present)v.text=std::make_shared<const std::string>(snapshotText(in,stringBudget));}}if(type==6 && v.bits && refs.symbolCount && v.bits>*refs.symbolCount)throw std::runtime_error("Invalid 2SAJ snapshot string symbol");return coerce(std::move(v),type);};
    for(auto& [name,entry]:pending){if(snapshotText(in,nameBudget)!=name || in.u32()!=entry.value.type || in.u32()!=unsigned(entry.constant))throw std::runtime_error("2SAJ snapshot schema differs");if(entry.value.type>=9){entry.elements.clear();auto count=in.count(8,8192);if(entry.constant && count)throw std::runtime_error("2SAJ snapshot constant array differs");if(count>262144-elements)throw std::runtime_error("2SAJ snapshot array budget exceeded");elements+=count;for(unsigned i=0;i<count;++i){auto index=in.u32();if(index>=8192 || !entry.elements.emplace(index,value(std::uint8_t(entry.value.type-5))).second)throw std::runtime_error("Invalid 2SAJ snapshot array index");}}else{auto restored=value(entry.value.type);if(entry.constant && (restored.bits!=entry.value.bits || bool(restored.text)!=bool(entry.value.text) || (restored.text && *restored.text!=*entry.value.text)))throw std::runtime_error("2SAJ snapshot constant differs");entry.value=std::move(restored);}}
    in.finish();entries_=std::move(pending);elementCount_=elements;
}

}
